  "literacy.tutorial.step3Desc": "वयं भवतः कच्चामालस्य दैनिकश्रमव्ययस्य च गणनां कुर्मः येन भवान् कदापि स्वस्य योग्यार्जनात् न्यूनं न विक्रयति।",
